/* From Uiverse.io by neitt0  - Tags:  */
/* The switch - the box around the slider */
.__UIV_SCOPE__ .switch {
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 8em;
  height: 4em;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ .switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

/* The slider */
.__UIV_SCOPE__ .slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #ccc;
  transition: 0.4s;
}

.__UIV_SCOPE__ .slider:before {
  position: absolute;
  content: "";
  height: 4em;
  width: 4em;
  background-color: white;
  transition: 0.2s;
  transition-timing-function: cubic-bezier(0.75, 0.02, 0.86, 1.31);
  transform-origin: bottom right;
}

.__UIV_SCOPE__ .switch input:checked + .slider {
  background-color: #2196f3;
}

.__UIV_SCOPE__ .switch input:focus + .slider {
  box-shadow: 0 0 1px #2196f3;
}

.__UIV_SCOPE__ .switch input:checked + .slider:before {
  transform: translateX(0em) rotate(90deg);
}
